const releaseStuckScheduledNotifications = `-- name: ReleaseStuckScheduledNotifications :execrows
UPDATE scheduled_notifications
SET status = 'pending', locked_at = NULL
WHERE status = 'processing' AND locked_at < $1::timestamptz
`

func (q *Queries) ReleaseStuckScheduledNotifications(ctx context.Context, staleBefore pgtype.Timestamptz) (int64, error) {
	result, err := q.db.Exec(ctx, releaseStuckScheduledNotifications, staleBefore)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

